export interface ScreenshotMessage {
  type: 'vly-screenshot-request' | 'vly-screenshot-response' | 'vly-screenshot-error';
  requestId?: string;
  dataUrl?: string;
  error?: string;
  format?: 'png' | 'jpeg' | 'webp';
  quality?: number;
}

const HTML2CANVAS_SRC =
  'https://cdn.jsdelivr.net/npm/html2canvas-pro@2.0.4/dist/html2canvas-pro.min.js';
const HTML2CANVAS_TIMEOUT_MS = 20000;

// The parent (CenterContent) gives up 30s after posting the request, and the
// library load above can eat up to 20s of that on a cold CDN. Everything below
// is sized so a request that finds the library already loaded answers well
// inside the remaining window: ready wait + settle + capture + one blank retry.
const APP_READY_TIMEOUT_MS = 12000;
const APP_READY_POLL_MS = 250;
// Lets fonts, images and mount animations (framer-motion `initial` fades) land
// before the DOM is cloned. html2canvas copies inline styles at that instant.
const SETTLE_DELAY_MS = 1500;
const BLANK_RETRY_DELAY_MS = 3000;
const UNIFORM_SAMPLE_GRID = 12;
const UNIFORM_TOLERANCE = 2;

type Html2Canvas = (
  element: HTMLElement,
  options: Record<string, unknown>,
) => Promise<HTMLCanvasElement>;

let html2canvasLoadPromise: Promise<Html2Canvas> | null = null;
let screenshotListenerInitialized = false;

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function loadHtml2Canvas(): Promise<Html2Canvas> {
  const existing = (window as Window & { html2canvas?: Html2Canvas }).html2canvas;
  if (existing) return Promise.resolve(existing);
  if (html2canvasLoadPromise) return html2canvasLoadPromise;

  html2canvasLoadPromise = new Promise<Html2Canvas>((resolve, reject) => {
    let script = document.querySelector<HTMLScriptElement>(
      'script[data-vly-screenshot-library]',
    );

    if (!script) {
      script = document.createElement('script');
      script.src = HTML2CANVAS_SRC;
      script.async = true;
      script.dataset.vlyScreenshotLibrary = 'true';
      document.head.appendChild(script);
    }

    const startedAt = Date.now();
    const poll = window.setInterval(() => {
      const runtime = (
        window as Window & { html2canvas?: Html2Canvas }
      ).html2canvas;

      if (runtime) {
        window.clearInterval(poll);
        resolve(runtime);
        return;
      }

      if (Date.now() - startedAt >= HTML2CANVAS_TIMEOUT_MS) {
        window.clearInterval(poll);
        if (script?.dataset.vlyScreenshotLibrary) {
          script.remove();
        }
        reject(new Error('Screenshot library did not finish loading'));
      }
    }, 100);
  }).catch((error) => {
    html2canvasLoadPromise = null;
    throw error;
  });

  return html2canvasLoadPromise;
}

/**
 * True once something visible is laid out in the viewport. An unmounted React
 * app is `<div id="root"></div>` with a zero-height body, and that is exactly
 * the state a fixed delay used to capture as a pure white image whenever the
 * dev server, Convex auth or a lazy route chunk was slower than the parent's
 * request. Deliberately not tied to `#root`: imported repos and other stacks
 * mount elsewhere.
 */
function hasRenderedContent(): boolean {
  const body = document.body;
  if (!body) return false;
  for (const child of Array.from(body.children)) {
    if (child instanceof HTMLScriptElement || child instanceof HTMLStyleElement) {
      continue;
    }
    const rect = child.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) return true;
  }
  return false;
}

/**
 * `deadline` is measured from when the REQUEST arrived, not from when this
 * starts: a cold CDN can spend up to 20s loading the library first, and the
 * parent gives up 30s after posting. Anchoring here keeps the worst case
 * (20s library + ready wait + settle + one retry) inside that window.
 */
async function waitForAppReady(deadline: number): Promise<void> {
  while (!hasRenderedContent() && Date.now() < deadline) {
    await delay(APP_READY_POLL_MS);
  }
  // `document.fonts` is absent in some embedded/test environments.
  await document.fonts?.ready?.catch(() => undefined);
  await delay(SETTLE_DELAY_MS);
}

/**
 * Samples a grid of pixels and reports whether they are all (near) the same
 * colour. A capture taken before the app painted, or while a page-level
 * mount animation still holds everything at opacity 0, is one flat colour;
 * a rendered page never is. Pure so it can be tested without a canvas.
 */
export function isUniformPixels(
  data: ArrayLike<number>,
  width: number,
  height: number,
  grid = UNIFORM_SAMPLE_GRID,
  tolerance = UNIFORM_TOLERANCE,
): boolean {
  if (width <= 0 || height <= 0) return true;
  let first: number[] | null = null;
  for (let gy = 0; gy < grid; gy++) {
    for (let gx = 0; gx < grid; gx++) {
      const x = Math.min(width - 1, Math.floor(((gx + 0.5) * width) / grid));
      const y = Math.min(height - 1, Math.floor(((gy + 0.5) * height) / grid));
      const offset = (y * width + x) * 4;
      if (!first) {
        first = [data[offset], data[offset + 1], data[offset + 2], data[offset + 3]];
        continue;
      }
      for (let c = 0; c < 4; c++) {
        if (Math.abs(data[offset + c] - first[c]) > tolerance) return false;
      }
    }
  }
  return true;
}

function isBlankCanvas(canvas: HTMLCanvasElement): boolean {
  const { width, height } = canvas;
  if (width <= 0 || height <= 0) return true;
  const context = canvas.getContext('2d');
  if (!context) return false;
  const { data } = context.getImageData(0, 0, width, height);
  return isUniformPixels(data, width, height);
}

function capture(html2canvas: Html2Canvas): Promise<HTMLCanvasElement> {
  return html2canvas(document.body, {
    useCORS: true,
    allowTaint: false,
    backgroundColor: '#ffffff',
    logging: false,
    scale: 0.5,
    width: window.innerWidth,
    height: window.innerHeight,
  });
}

export function initScreenshotListener() {
  if (screenshotListenerInitialized) return;
  screenshotListenerInitialized = true;
  // Start loading immediately, while still keeping request handling resilient
  // if the first capture arrives before the script has finished.
  void loadHtml2Canvas().catch((error) => {
    console.warn('[VLY Screenshot] Failed to preload screenshot library', error);
  });

  // Listen for screenshot requests from parent
  window.addEventListener('message', async (event) => {
    const message = event.data as ScreenshotMessage | null;

    // Anything on the page may postMessage a string or null into this window;
    // reading `.type` off it used to throw and surface in the parent as a
    // fake build error via the plugin's unhandledrejection hook.
    if (!message || typeof message !== 'object') return;
    if (message.type !== 'vly-screenshot-request') return;

    const readyDeadline = Date.now() + APP_READY_TIMEOUT_MS;

    try {
      // The parent can request a screenshot shortly after the iframe loads.
      // Wait for the CDN library instead of failing the first attempt.
      const html2canvas = await loadHtml2Canvas();
      await waitForAppReady(readyDeadline);

      if (window.innerWidth === 0 || window.innerHeight === 0) {
        throw new Error('Preview viewport has no size');
      }

      let canvas = await capture(html2canvas);
      if (isBlankCanvas(canvas)) {
        // Flat colour = nothing painted yet. One more try after a pause is
        // cheaper than uploading a blank thumbnail that the content-hash
        // dedupe then keeps until the next commit.
        await delay(BLANK_RETRY_DELAY_MS);
        canvas = await capture(html2canvas);
        if (isBlankCanvas(canvas)) {
          // Still flat: report it rather than replace a good thumbnail with
          // a blank one. The parent counts it as a failed attempt.
          throw new Error('Preview rendered blank before capture');
        }
      }

      // Convert to data URL. Keeping this synchronous avoids errors thrown
      // inside HTMLCanvasElement.toBlob callbacks bypassing the catch above.
      const format = message.format || 'jpeg';
      const quality = message.quality || 0.85;
      const mimeType = `image/${format}`;
      const dataUrl = canvas.toDataURL(mimeType, quality);

      window.parent.postMessage({
        type: 'vly-screenshot-response',
        requestId: message.requestId,
        dataUrl,
      } as ScreenshotMessage, '*');

    } catch (error) {

      window.parent.postMessage({
        type: 'vly-screenshot-error',
        requestId: message.requestId,
        error: error instanceof Error ? error.message : 'Unknown error',
      } as ScreenshotMessage, '*');
    }
  });
}
